options(survey.lonely.psu='adjust');r<-'./TB_metabolome_exposome_20261115_2130';o<-'./系统复审与优化_20261116';.libPaths(c(file.path(r,'analysis_MWAS_ExWAS/Rlib'),.libPaths()));suppressPackageStartupMessages(library(survey));d<-readRDS(file.path(r,'临床升级_双组学_20261116/output/analysis_data_private.rds'));a<-d$data;w<-as.data.frame(readRDS(file.path(r,'output/2011-2012/NHANES_2011-2012_full_population_wide_TBflags.rds')));w<-w[match(a$SEQN,w$SEQN),];stopifnot(all(w$SEQN==a$SEQN));a$BMI<-w$BMXBMI;a$y<-ifelse(a$qvalid&!is.na(a$tst10)&a$QFT==1&a$tst10==0,1,ifelse(a$qvalid&!is.na(a$tst10)&a$QFT==0&a$tst10==1,0,NA));a$smoking<-factor(a$smoking);v<-c('x_LBXBCD','BMI','fa_n3');cv<-c('age','sex_male','birth','smoking');mask<-a$adult&!is.na(a$y)&complete.cases(a[,c(v,cv)])&is.finite(a$WTFAS2YR)&a$WTFAS2YR>0;mask[is.na(mask)]<-FALSE;sc<-data.frame(variable=v,mean=sapply(v,function(x)mean(a[[x]][mask])),sd=sapply(v,function(x)sd(a[[x]][mask])));for(j in seq_along(v))a[[paste0('z',j)]]<-(a[[v[j]]]-sc$mean[j])/sc$sd[j];a$.dom<-mask;keep<-is.finite(a$WTFAS2YR)&a$WTFAS2YR>0&!is.na(a$SDMVSTRA)&!is.na(a$SDMVPSU);des<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTFAS2YR,nest=TRUE,data=a[keep,]);des<-subset(des,.dom);eq<-list(BMI=list(f=z2~z1+age+sex_male+birth+smoking,terms='z1'),n3=list(f=z3~z1+z2+age+sex_male+birth+smoking,terms=c('z1','z2')),discordance=list(f=y~z1+z2+z3+age+sex_male+birth+smoking,terms=c('z1','z2','z3')));out<-list();for(nm in names(eq)){fit<-svyglm(eq[[nm]]$f,des,family=if(nm=='discordance')quasibinomial()else gaussian());for(t in eq[[nm]]$terms){b<-coef(fit)[t];s<-sqrt(diag(vcov(fit)))[t];df<-fit$df.residual;out[[length(out)+1]]<-data.frame(equation=nm,term=t,n=nrow(des$variables),qft_only=sum(des$variables$y==1),tst_only=sum(des$variables$y==0),ess=sum(des$variables$WTFAS2YR)^2/sum(des$variables$WTFAS2YR^2),design_df=degf(des),residual_df=df,b=unname(b),low=unname(b-qt(.975,df)*s),high=unname(b+qt(.975,df)*s),p=unname(2*pt(-abs(b/s),df)),converged=fit$converged)}};z<-do.call(rbind,out);z$q_BH<-p.adjust(z$p,'BH');write.csv(z,file.path(o,'数据表/11_低维路径模型.csv'),row.names=FALSE);write.csv(sc,file.path(o,'数据表/12_低维路径标准化.csv'),row.names=FALSE);print(z);cat('exploratory post hoc low-dimensional model; association only\n')
